???import { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import api, { getTrendingPosts } from "../api/axios";
import Navbar from "../components/layout/Navbar";
import PostCard from "../components/layout/PostCard";
import TrendingCard from "../components/layout/TrendingCard";

const PostModal = ({ post, onClose }) => {
  useEffect(() => {
    // Disable body scroll when modal opens
    document.body.style.overflow = "hidden";

    // Add ESC key listener to close modal
    const handleKeyDown = (e) => {
      if (e.key === "Escape") onClose();
    };
    window.addEventListener("keydown", handleKeyDown);

    return () => {
      // Re-enable body scroll and remove listener when modal closes
      document.body.style.overflow = "auto";
      window.removeEventListener("keydown", handleKeyDown);
    };
  }, [onClose]);

  if (!post) return null;

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4 animate-fadeIn"
      onClick={onClose}
    >
      <div
        className="bg-white rounded-xl w-full max-w-4xl max-h-[90vh] overflow-y-auto shadow-xl animate-scaleIn relative"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Close button */}
        <button
          onClick={onClose}
          className="absolute top-4 right-4 text-gray-500 hover:text-gray-900 bg-white/80 p-1 rounded-full z-10 transition-colors"
        >
          <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2.5} stroke="currentColor" className="w-6 h-6">
            <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
          </svg>
        </button>

        <div className="p-6 md:p-8">
          {/* We reuse the PostCard component conceptually, but the modal contains the full post.
              Since PostCard already has full UI, we can render it directly or reconstruct if needed. 
              To avoid infinite nesting hooks inside PostCard we just render it here. */}
          <PostCard post={post} isModal={true} />
        </div>
      </div>
    </div>
  );
};

const Feed = () => {
  const [posts, setPosts] = useState([]);
  const [trendingPosts, setTrendingPosts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [selectedPost, setSelectedPost] = useState(null);

  // Fetch Posts
  const fetchPosts = async () => {
    try {
      setLoading(true);
      setError("");

      const userInfo = JSON.parse(localStorage.getItem("userInfo") || "null");

      if (!userInfo?.token) {
        throw new Error("Please login again.");
      }

      const response = await api.get("/posts");

      if (!Array.isArray(response.data)) {
        throw new Error("Invalid posts format from backend.");
      }

      setPosts(response.data);
    } catch (err) {
      setError(err.response?.data?.message || err.message);
      setPosts([]);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchPosts();
  }, []);

  // Trending Posts (server-side ranking)
  const fetchTrending = async () => {
    try {
      const res = await getTrendingPosts(3);
      setTrendingPosts(res || []);
    } catch (err) {
      // fallback: compute client-side from net votes
      setTrendingPosts(
        [...posts]
          .sort(
            (a, b) =>
              (b.upvoteCount || 0) -
              (b.downvoteCount || 0) -
              ((a.upvoteCount || 0) - (a.downvoteCount || 0))
          )
          .slice(0, 3)
      );
    }
  };

  useEffect(() => {
    fetchTrending();
  }, [posts]); // Re-fetch trending if posts change (for client-side fallback)

  return (
    <div className="flex-1 w-full px-4 md:px-8 pb-12 relative flex flex-col">
      {/* Antigravity Mesh Background */}
      <div className="bg-mesh-gradient fixed inset-0 z-[-1]" />

      {/* MASTER CONTAINER */}
      <div className="w-full max-w-[1400px] mx-auto flex-1 relative z-10 flex flex-col lg:flex-row gap-8 lg:gap-12 mt-4 md:mt-8">

        {/* ================= LEFT FEED ================= */}
        <div className="flex-1 w-full lg:max-w-3xl xl:max-w-4xl flex flex-col gap-6 mx-auto">

          {/* Main Feed Activity Area */}
          <div className="flex flex-col gap-6">
            {loading ? (
              // Skeleton Loaders
              [1, 2, 3].map((n) => (
                <div key={n} className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm animate-pulse">
                  <div className="flex items-center gap-3 mb-4">
                    <div className="w-10 h-10 bg-gray-200 rounded-full"></div>
                    <div className="flex-1">
                      <div className="h-4 bg-gray-200 rounded w-1/4 mb-2"></div>
                      <div className="h-3 bg-gray-100 rounded w-1/6"></div>
                    </div>
                  </div>
                  <div className="h-24 bg-gray-50 rounded mb-4"></div>
                  <div className="h-8 bg-gray-100 rounded w-1/3"></div>
                </div>
              ))
            ) : posts.length > 0 ? (
              posts.map((post) => (
                <div key={post._id} onClick={() => setSelectedPost(post)} className="cursor-pointer">
                  <PostCard post={post} />
                </div>
              ))
            ) : (
              <div className="text-center py-10 bg-white rounded-xl shadow-sm border border-gray-100">
                <p className="text-gray-500">No recent activity matching your criteria.</p>
              </div>
            )}
          </div>
          {/* Error */}
          {error && (
            <div className="bg-red-100 border border-red-200 text-red-500 p-4 rounded-xl shadow-sm">
              <p>{error}</p>
              <button
                onClick={fetchPosts}
                className="mt-3 px-4 py-2 bg-red-500 text-white rounded-lg shadow-sm font-bold hover:bg-red-600 transition"
              >
                Retry
              </button>
            </div>
          )}
        </div>

        {/* ================= RIGHT SIDEBAR ================= */}
        <div className="w-full lg:w-[350px] xl:w-[380px] space-y-8 flex-shrink-0">

          {/* Trending Discussions inside the generic Right Sidebar block */}
          <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
            <h3 className="text-lg font-bold text-gray-900 mb-4 border-l-4 border-amber-500 pl-4">Trending Discussions</h3>
            <TrendingCard trendingPosts={trendingPosts} loading={loading} />
          </div>

          {/* AI Thought Starter */}
          <div className="relative bg-white border border-gray-100 rounded-2xl p-6 shadow-sm overflow-hidden">
            <div className="absolute left-0 top-0 h-full w-[4px] bg-[#8C7851]" />
            <h2 className="font-bold text-[#1A1A1A] mb-3 pl-2">AI Thought Starter</h2>

            <p className="text-sm text-gray-600 mb-6 pl-2">
              What's one thing your team should stop doing immediately?
            </p>

            <Link to="/write" className="btn-primary w-full">
              Write Reflection
            </Link>
          </div>

        </div>
      </div>

      {/* Post Modal */}
      {selectedPost && (
        <PostModal post={selectedPost} onClose={() => setSelectedPost(null)} />
      )}
    </div>
  );
};

export default Feed;
